{"argv":["bash","-lc","cat > robust_exp.py <<'PY'
from research import *
from sklearn.linear_model import QuantileRegressor
import warnings;warnings.filterwarnings('ignore')

def evalrob(cols,kind='qr',a=.01,mode='all',ret=False):
 inds=[names.index(k) for k in cols];xp=X[:,inds];pr=np.zeros(len(y));trainmask=el if mode=='eligible' else ts>=3
 for p in groups:
  tr=(g!=p)&trainmask;te=g==p
  sc=StandardScaler().fit(xp[tr]);xx=sc.transform(xp)
  if kind=='qr':m=QuantileRegressor(alpha=a,solver='highs')
  if kind=='huber':m=HuberRegressor(alpha=a,max_iter=400,epsilon=1.15)
  counts=Counter(g[tr]);w=np.array([1/counts[q] for q in g[tr]]);w*=len(w)/w.sum()
  m.fit(xx[tr],y[tr],sample_weight=w);pr[te]=m.predict(xx[te])
 errs={p:np.mean(np.abs(pr[(g==p)&el]-y[(g==p)&el])) for p in groups if any((g==p)&el)}
 if ret:return pr,errs
 return np.mean(list(errs.values()))
if __name__=='__main__':
 res=[]
 for sn in ['time','hrtime','basic','phys2','summary']:
  for kind,aa in [('qr',[0,.001,.01,.03,.05,.1]),('huber',[.1,1,10,100])]:
   for a in aa:
    for mode in ['all','eligible']:
     e=evalrob(sets[sn],kind,a,mode);res.append((float(e),kind,sn,a,mode));print(res[-1],flush=True)
 print('BEST',sorted(res)[:30]);json.dump(sorted(res),open('robust_results.json','w'))
PY
OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 python3 robust_exp.py > robust_out.txt; tail -3 robust_out.txt"]}

